-- Preserve timeless examination fixtures; give existing live flows explicit deadlines.
UPDATE orders_details d SET expires_at=coalesce(updated_at,created_at)+ CASE WHEN status IN ('PENDING','RESERVING') THEN interval '5 minutes' ELSE interval '30 minutes' END
FROM orders o WHERE d.order_id=o.id AND d.expires_at IS NULL AND d.status IN ('PENDING','RESERVING','RESERVED','PAYMENT_PENDING') AND o.guid NOT IN ('49bb83f2-d138-3da6-a227-cb38461c652b','0f56eb50-83c7-3647-b3fa-9d7e5de61eb5','95552497-cafc-39c0-a56f-82653fea704e','87ba424c-d7b8-346f-bdd2-cadd11e9e10f','7c63a752-d8e1-3f9e-a761-b4174fa708d4','4b19d1d1-04e2-3712-a340-ee8527052f76','2f629a34-5680-30c8-b1b8-c7e72bb05dda','28745669-0c70-3d19-a1b9-4e4eaf38d744','002aa87d-53cc-39e2-86b8-0f76dfc0afcc','bffcd64b-d785-397f-8728-adde35159902','cfb54977-75e9-3179-a53f-63691012024a','b91f64f5-1517-3476-beb8-5ee5c32d7316','3c18fdbe-bdac-39e1-8cb9-64ddbc2636d4','84bcc3dc-d845-3587-8fc2-2c312258b802','06dfd605-516f-39dd-bbdf-612af31af056','ff72d525-ca93-3c5d-a3b7-2329cd3641b1','37c48458-9f13-357f-8dd6-511bae0b12e9','b989d806-7df1-3d51-891e-2c38720ff351','05001ffc-c6f4-31c7-b87e-eda291315c49','fac9e908-228e-3e73-b507-2c22e3d23785');
